"""Turn the intent into files: one frr.conf per router, the containerlab topology
and the Prometheus config. `netpulse configs` calls `render_all`.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

from jinja2 import Environment, PackageLoader, StrictUndefined

from netpulse.intent import Intent

DAEMONS = """\
# GENERATED by netpulse. Which FRR daemons to start.
zebra=yes
bgpd=yes
ospfd=yes
ospf6d=no
ripd=no
ripngd=no
isisd=yes
pimd=no
pim6d=no
ldpd=yes
nhrpd=no
eigrpd=no
babeld=no
sharpd=no
pbrd=no
bfdd=yes
fabricd=no
vrrpd=no
pathd=no
vtysh_enable=yes
zebra_options="  -A 127.0.0.1 -s 90000000"
mgmtd_options="  -A 127.0.0.1"
bgpd_options="   -A 127.0.0.1"
ospfd_options="  -A 127.0.0.1"
isisd_options="  -A 127.0.0.1"
ldpd_options="   -A 127.0.0.1"
staticd_options="-A 127.0.0.1"
bfdd_options="   -A 127.0.0.1"
"""

VTYSH_CONF = "service integrated-vtysh-config\n"

PROMETHEUS_IP = "172.20.20.91"
GRAFANA_IP = "172.20.20.92"


def _env() -> Environment:
    return Environment(
        loader=PackageLoader("netpulse", "templates"),
        undefined=StrictUndefined,  # a typo in a template variable is an error, not ""
        trim_blocks=True,
        lstrip_blocks=True,
        keep_trailing_newline=True,
    )


def router_context(intent: Intent, name: str) -> dict[str, Any]:
    """Everything the frr.conf template needs for one router, already computed."""
    dev = intent.devices[name]
    bfd = bool(intent.settings.get("bfd", True))

    interfaces = []
    for itf in intent.interfaces(name):
        interfaces.append(
            {
                "name": itf.name,
                "ip": str(itf.ip),
                "description": f"{itf.link_type} to {itf.peer}:{itf.peer_interface}",
                "isis": itf.link_type == "core",
            }
        )

    tunnels = []
    static_routes: list[tuple[str, str]] = []
    ospf: dict[str, Any] | None = None
    for t, side in intent.tunnels_of(name):
        local_ip = t.a_ip if side == "a" else t.b_ip
        peer = t.b if side == "a" else t.a
        tunnels.append(
            {"name": t.name, "ip": str(local_ip), "description": f"GRE to {peer} (OSPF inside)"}
        )
        # Reach the far tunnel endpoint via the internet link, never via the tunnel.
        peer_dev = intent.devices[peer]
        internet = next(i for i in intent.interfaces(name) if i.link_type == "internet")
        static_routes.append((f"{peer_dev.tunnel_endpoint}/32", str(internet.peer_ip.ip)))
        ospf = ospf or {"networks": [], "default_originate": False}
        ospf["networks"].append((str(t.subnet), t.ospf_area))
        if dev.role == "pop":
            # Only the real loopback and the LAN - not the tunnel endpoint (recursive routing!).
            ospf["networks"].append((f"{dev.loopback}/32", t.ospf_area))
            for itf in intent.interfaces(name):
                if itf.link_type == "lan":
                    ospf["networks"].append((str(itf.ip.network), t.ospf_area))
        else:
            ospf["default_originate"] = True

    bgp: dict[str, Any] | None = None
    neighbors = intent.bgp_neighbors(name)
    if neighbors:
        groups = sorted({n.group for n in neighbors}, key=["FABRIC", "EDGE", "IBGP"].index)
        redistribute = bool(ospf) and dev.role == "backbone"
        bgp = {
            "asn": dev.asn,
            "groups": groups,
            "neighbors": neighbors,
            "local_prefixes": intent.originated_prefixes(name),
            "redistribute_ospf": redistribute,
            "pop_prefixes": intent.pop_prefixes() if redistribute else [],
        }

    isis = None
    mpls = None
    if dev.role == "backbone":
        isis = {"net": dev.isis_net}
        if intent.settings.get("mpls_ldp"):
            mpls = {"interfaces": [i.name for i in intent.isis_neighbors(name)]}

    return {
        "name": name,
        "role": dev.role,
        "loopback": dev.loopback,
        "tunnel_endpoint": dev.tunnel_endpoint,
        "interfaces": interfaces,
        "tunnels": tunnels,
        "static_routes": static_routes,
        "bgp": bgp,
        "ospf": ospf,
        "isis": isis,
        "mpls": mpls,
        "bfd": bfd,
        "max_paths": intent.settings.get("ecmp_max_paths", 8),
    }


def node_execs(intent: Intent) -> dict[str, list[str]]:
    """Shell commands containerlab runs inside each node after it starts.

    FRR configures IP addresses and routing, but it cannot create a GRE device or
    flip kernel sysctls, so those are done here with iproute2 / sysctl.
    """
    execs: dict[str, list[str]] = {}
    for dev in intent.devices.values():
        cmds: list[str] = []
        if dev.is_router:
            # Docker gives every container a default route via the management
            # network (kernel route, distance 0). It would beat any default learned
            # by OSPF/BGP (distance 110/20) and leak lab traffic out of eth0.
            # The mgmt subnet is directly connected, so docker exec still works.
            cmds.append("ip route del default")
        if dev.role == "host":
            ip = intent.interfaces(dev.name)[0]
            gw = ip.peer_ip.ip
            cmds += [
                f"ip addr add {ip.ip} dev {ip.name}",
                # Keep the management default route; send lab traffic to the leaf/POP.
                f"ip route add 10.0.0.0/8 via {gw}",
                f"ip route add 192.168.0.0/16 via {gw}",
            ]
        for t, side in intent.tunnels_of(dev.name):
            peer = intent.devices[t.b if side == "a" else t.a]
            cmds += [
                f"ip tunnel add {t.name} mode gre local {dev.tunnel_endpoint} "
                f"remote {peer.tunnel_endpoint} ttl 64",
                f"ip link set {t.name} up",
            ]
        if dev.role == "backbone" and intent.settings.get("mpls_ldp"):
            cmds.append("sysctl -w net.mpls.platform_labels=100000")
            for itf in intent.isis_neighbors(dev.name):
                cmds.append(f"sysctl -w net.mpls.conf.{itf.name}.input=1")
        execs[dev.name] = cmds
    return execs


def render_router(intent: Intent, name: str) -> str:
    return _env().get_template("frr.conf.j2").render(**router_context(intent, name))


def render_topology(intent: Intent) -> str:
    return (
        _env()
        .get_template("netlab.clab.yml.j2")
        .render(
            intent=intent,
            routers=intent.routers(),
            hosts=intent.hosts(),
            execs=node_execs(intent),
            monitoring={"prometheus_ip": PROMETHEUS_IP, "grafana_ip": GRAFANA_IP},
        )
    )


def render_prometheus(intent: Intent) -> str:
    port = intent.settings.get("exporter_port", 9101)
    return (
        "# GENERATED by `netpulse configs`.\n"
        "global:\n"
        "  scrape_interval: 5s\n"
        "  evaluation_interval: 5s\n"
        "scrape_configs:\n"
        "  - job_name: netpulse\n"
        "    static_configs:\n"
        f"      - targets: ['{intent.mgmt['gateway']}:{port}']\n"
        "  - job_name: prometheus\n"
        "    static_configs:\n"
        "      - targets: ['localhost:9090']\n"
    )


def render_all(intent: Intent, root: str | Path = ".") -> list[Path]:
    """Write every generated file. Returns the paths written."""
    root = Path(root)
    written: list[Path] = []

    def write(rel: str, text: str) -> None:
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8", newline="\n")
        written.append(path)

    write("configs/common/daemons", DAEMONS)
    write("configs/common/vtysh.conf", VTYSH_CONF)
    for dev in intent.routers():
        write(f"configs/{dev.name}/frr.conf", render_router(intent, dev.name))
    write("clab/netlab.clab.yml", render_topology(intent))
    write("monitoring/prometheus.yml", render_prometheus(intent))
    return written
